"""Figures for "Portfolio Risk Management".

Every number below is copied from the lesson text it is embedded in. The
lessons computed them from Yahoo Finance daily adjusted closes pulled on
2026-09-24 (series end 2026-09-23); the pulls and calculations are described
in each lesson's Worked example. Run from this directory:

    cd figures && python3 make_figures.py
"""
import sys; from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[4] / "scripts"))
from svgfig import *

BLUE, YELLOW, RED, GREEN = COLORS[1], COLORS[2], COLORS[3], COLORS[0]


def pct(v):
    return f"{v:+.1f}%"


def two_line_labels(path, label_pairs):
    """bar_chart writes one-line x labels; these charts need two lines under
    each bar, so they are generated with blank labels and the pairs are added
    here using the same slot geometry as bar_chart."""
    svg = Path(path).read_text()
    slot = (W - PAD_L - PAD_R) / len(label_pairs)
    extra = []
    for i, (top, bottom) in enumerate(label_pairs):
        x = PAD_L + i * slot + slot / 2
        for j, text in enumerate((top, bottom)):
            y = H - PAD_B + 18 + j * 13
            extra.append(f"<text x='{x:.1f}' y='{y}' fill='{MUTED}' text-anchor='middle' font-size='11'>{text}</text>")
    Path(path).write_text(svg.replace("</svg>", "\n".join(extra) + "\n</svg>"))


