def book_daily_pnl_distribution():
    """Lesson 4: histogram of the book's 251 daily returns (2025-09-24 to
    2026-09-23) in 0.25% bins; the historical 95% VaR cut is -0.90%, so the
    three bins at or below -1.00% hold the tail that VaR and ES describe."""
    lower = [-1.50, -1.25, -1.00, -0.75, -0.50, -0.25, 0.00, 0.25, 0.50, 0.75, 1.00, 1.25, 1.50, 1.75, 2.00, 2.25]
    counts = [5, 4, 11, 25, 36, 34, 42, 40, 30, 10, 9, 2, 1, 0, 0, 2]
    labels = [f"{v:+.2f}" for v in lower]
    colors = [RED if v <= -1.00 else BLUE for v in lower]
    bar_chart("book-daily-pnl-distribution.svg", labels, counts, colors=colors,
              title="Book daily returns, 251 days to 2026-09-23 (bin lower edge, %)", y_label="days",
              y_fmt=lambda v: f"{v:.0f}")
    svg = Path("book-daily-pnl-distribution.svg").read_text()
    note = (f"<text x='{PAD_L + 6}' y='{PAD_T + 16}' fill='{TEXT}' font-size='11'>red bins: at or below the 95% cut "
            f"(historical VaR -0.90% = -$9,044; parametric -1.00% = -$9,972; ES -$11,924)</text>")
    Path("book-daily-pnl-distribution.svg").write_text(svg.replace("</svg>", note + "\n</svg>"))


def sector_correlations_calm_vs_crisis():
    """Lesson 5: daily-return correlations for eight pairs in calm 2017
    (251 days) and in the crisis window 2020-02-20 to 2020-04-30 (50 days)."""
    pairs = ["XLK-XLF", "XLE-XLU", "XLV-XLY", "SPY-EFA", "SPY-EEM", "SPY-HYG", "SPY-TLT", "SPY-GLD"]
    calm = [0.37, -0.03, 0.39, 0.69, 0.62, 0.68, -0.33, -0.25]
    crisis = [0.92, 0.66, 0.89, 0.96, 0.93, 0.84, -0.50, 0.22]
    values, colors, label_pairs = [], [], []
    for p, c, k in zip(pairs, calm, crisis):
        values += [c, k]; colors += [BLUE, RED]; label_pairs += [(p, "2017"), (p, "2020")]
    bar_chart("sector-correlations-calm-vs-crisis.svg", [""] * 16, values, colors=colors,
              title="Pairwise correlation, calm 2017 (blue) vs Feb-Apr 2020 (red)", y_label="correlation",
              y_fmt=lambda v: f"{v:+.2f}")
    two_line_labels("sector-correlations-calm-vs-crisis.svg", label_pairs)


def drawdown_derisking_rule_flow():
    """Lesson 7: the drawdown-based de-risking rule tested on SPY."""
    flow_diagram("drawdown-derisking-rule-flow.svg",
                 ["Mark NAV against its 252-day peak", "Drawdown under 10%: full gross", "10% to 20%: gross x 0.5",
                  "Over 20%: gross x 0", "Re-add only on a new 50-day high"],
                 title="Drawdown de-risking rule (tested on SPY, 2008 to 2025)",
                 notes=["daily, at the close", "2025: cut on 03-13 at -10.0%, restored 05-13",
                        "2020: cut 02-27 at -12.1%", "2020: flat 03-12 at -26.7%, 7 sessions before the low",
                        "2020: back in 05-20; rule +1.8% vs +17.2% buy-and-hold"])


def gate_stack_flow():
    """Lesson 8: the five gates a strategy must pass, with the RSI(2)-on-SPY
    test results from the lesson."""
    flow_diagram("gate-stack-flow.svg",
                 ["Sample size: 60+ trades", "Out-of-sample replication", "Cost survival at 10 bps",
                  "Correlation to the book under 0.5", "Beats cash (BIL)"],
                 title="The gate stack, with the RSI(2)-on-SPY test",
                 notes=["76 OOS trades 2018-2026 (72 in-sample 2008-2017)", "+0.54%/trade OOS vs +0.57% in-sample; t = 3.2",
                        "+0.44%/trade after 10 bps; still positive", "0.35 to SPY daily; passes",
                        "+49.4% on 261 days vs +24.6% BIL over 8.7 yrs; idle cash earns BIL"])


def tail_hedge_calendar_returns():
    """Lesson 9: Cambria Tail Risk ETF (TAIL) calendar-year total returns
    2018 to 2026 YTD (to 2026-09-23), plus the 2020-02-19 to 2020-03-23 crash
    window, from Yahoo adjusted closes."""
    labels = ["2018", "2019", "2020", "2021", "2022", "2023", "2024", "2025", "2026 YTD", "Feb-Mar 2020"]
    values = [2.9, -14.3, 6.9, -12.8, -13.1, -13.3, -9.6, 5.5, -12.5, 28.4]
    colors = [YELLOW if lab == "Feb-Mar 2020" else (GREEN if v >= 0 else RED) for lab, v in zip(labels, values)]
    bar_chart("tail-hedge-calendar-returns.svg", labels, values, colors=colors,
              title="TAIL ETF total return by calendar year, and the 2020 crash window", y_label="%", y_fmt=pct)


